// NewConfirmIntentRequestBody builds the HTTP request body from the payload of
// the "confirm_intent" endpoint of the "surla" service.
func NewConfirmIntentRequestBody(p *surla.ConfirmIntentPayload) *ConfirmIntentRequestBody {
	body := &ConfirmIntentRequestBody{
		ChangeID:        p.ChangeID,
		RequestRevision: p.RequestRevision,
	}
	if p.Answers != nil {
		body.Answers = make(map[string]string, len(p.Answers))
		for key, val := range p.Answers {
			tk := key
			tv := val
			body.Answers[tk] = tv
		}
	}
	if p.Examples != nil {
		body.Examples = make([]*ExampleItemRequestBody, len(p.Examples))
		for i, val := range p.Examples {
			if val == nil {
				body.Examples[i] = nil
				continue
			}
			body.Examples[i] = marshalSurlaExampleItemToExampleItemRequestBody(val)
		}
	} else {
		body.Examples = []*ExampleItemRequestBody{}
	}
	return body
}

